def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    horses = image_patch.find("horse")
    outhouses = image_patch.find("outhouse")

    if not horses or not outhouses:
        return image_patch

    near_outhouses = [h for h in horses if distance(h, outhouses[0]) < 0]

    if not near_outhouses:
        return image_patch

    taller_horses = [h for h in near_outhouses if h.verify_property("horse", "taller")]

    if not taller_horses:
        return near_outhouses[0]

    return tallest_horse(near_outhouses)

def tallest_horse(horses: List[ImagePatch]) -> ImagePatch:
    return max(horses, key=lambda h: h.vertical_center)

